/* Minimal local jsPDF-compatible bundle for SHEARiQ PDF exports. */
(function(global){
  function esc(value){return String(value == null ? '' : value).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)').replace(/[\r\n]+/g,' ');}
  function pad(n){return String(n).padStart(2,'0');}
  function formatDate(d){return "D:"+d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate())+pad(d.getHours())+pad(d.getMinutes())+pad(d.getSeconds());}
  class jsPDF{
    constructor(options){
      options = options || {};
      this.orientation = options.orientation || 'portrait';
      this.unit = options.unit || 'mm';
      this.format = options.format || 'a4';
      this.pageWidth = this.orientation === 'landscape' ? 297 : 210;
      this.pageHeight = this.orientation === 'landscape' ? 210 : 297;
      this.pages = [[]];
      this.fontSize = 10;
      this.fontStyle = 'normal';
      this.textColor = [0,0,0];
      this.internal = {
        pageSize: { getWidth: () => this.pageWidth, getHeight: () => this.pageHeight },
        getNumberOfPages: () => this.pages.length
      };
    }
    setFont(_family, style){ this.fontStyle = style || 'normal'; return this; }
    setFontSize(size){ this.fontSize = Number(size) || this.fontSize; return this; }
    setTextColor(r,g,b){ this.textColor = [r||0,g||0,b||0]; return this; }
    setDrawColor(){ return this; }
    setFillColor(){ return this; }
    setLineWidth(){ return this; }
    line(x1,y1,x2,y2){ this.pages[this.pages.length-1].push({type:'line',x1,y1,x2,y2}); return this; }
    rect(){ return this; }
    addPage(){ this.pages.push([]); return this; }
    setPage(pageNumber){ this._pageNumber = Math.max(1, Math.min(this.pages.length, pageNumber)); return this; }
    text(value, x, y, options){
      const pageIndex = (this._pageNumber || this.pages.length) - 1;
      const lines = Array.isArray(value) ? value : String(value == null ? '' : value).split('\n');
      this.pages[pageIndex].push({type:'text', lines, x:Number(x)||0, y:Number(y)||0, size:this.fontSize, style:this.fontStyle, color:this.textColor, align:options&&options.align});
      return this;
    }
    splitTextToSize(value, maxWidth){
      const text = String(value == null ? '' : value);
      const charWidth = Math.max(this.fontSize * 0.36, 1.8);
      const maxChars = Math.max(Math.floor((Number(maxWidth)||80) / charWidth), 8);
      const out = [];
      text.split(/\n/).forEach((paragraph) => {
        let line = '';
        paragraph.split(/\s+/).forEach((word) => {
          if (!word) return;
          const next = line ? line + ' ' + word : word;
          if (next.length > maxChars && line) { out.push(line); line = word; }
          else line = next;
        });
        out.push(line || '');
      });
      return out;
    }
    output(type){
      const pdf = this._buildPdf();
      if (type === 'blob') return new Blob([pdf], {type:'application/pdf'});
      return pdf;
    }
    save(filename){
      const blob = this.output('blob');
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = filename || 'document.pdf'; a.style.display = 'none';
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 0);
      return this;
    }
    _buildContent(page){
      const chunks = [];
      const scale = 72 / 25.4;
      page.forEach((item) => {
        if (item.type === 'text') {
          const fontName = item.style === 'bold' ? '/F2' : '/F1';
          const [r,g,b] = item.color || [0,0,0];
          let y = (this.pageHeight - item.y) * scale;
          item.lines.forEach((line, index) => {
            const xMm = item.align === 'right' ? item.x - (String(line).length * item.size * 0.18) : item.x;
            const x = xMm * scale;
            chunks.push(`BT ${fontName} ${item.size} Tf ${(r/255).toFixed(3)} ${(g/255).toFixed(3)} ${(b/255).toFixed(3)} rg ${x.toFixed(2)} ${(y - index * item.size * 0.45).toFixed(2)} Td (${esc(line)}) Tj ET`);
          });
        } else if (item.type === 'line') {
          chunks.push(`${(item.x1*scale).toFixed(2)} ${((this.pageHeight-item.y1)*scale).toFixed(2)} m ${(item.x2*scale).toFixed(2)} ${((this.pageHeight-item.y2)*scale).toFixed(2)} l S`);
        }
      });
      return chunks.join('\n');
    }
    _buildPdf(){
      const objects = [];
      const add = (body) => { objects.push(body); return objects.length; };
      const font1 = add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
      const font2 = add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');
      const pageIds = [];
      this.pages.forEach((page) => {
        const content = this._buildContent(page);
        const contentId = add(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);
        const pageId = add(`<< /Type /Page /Parent 0 0 R /MediaBox [0 0 ${(this.pageWidth*72/25.4).toFixed(2)} ${(this.pageHeight*72/25.4).toFixed(2)}] /Resources << /Font << /F1 ${font1} 0 R /F2 ${font2} 0 R >> >> /Contents ${contentId} 0 R >>`);
        pageIds.push(pageId);
      });
      const pagesId = add(`<< /Type /Pages /Kids [${pageIds.map(id=>id+' 0 R').join(' ')}] /Count ${pageIds.length} >>`);
      pageIds.forEach((id) => { objects[id-1] = objects[id-1].replace('/Parent 0 0 R', `/Parent ${pagesId} 0 R`); });
      const catalogId = add(`<< /Type /Catalog /Pages ${pagesId} 0 R >>`);
      const infoId = add(`<< /Producer (SHEARiQ local jsPDF bundle) /CreationDate (${formatDate(new Date())}) >>`);
      let pdf = '%PDF-1.4\n';
      const offsets = [0];
      objects.forEach((body, i) => { offsets.push(pdf.length); pdf += `${i+1} 0 obj\n${body}\nendobj\n`; });
      const xref = pdf.length;
      pdf += `xref\n0 ${objects.length+1}\n0000000000 65535 f \n` + offsets.slice(1).map(o => String(o).padStart(10,'0')+' 00000 n ').join('\n') + '\n';
      pdf += `trailer\n<< /Size ${objects.length+1} /Root ${catalogId} 0 R /Info ${infoId} 0 R >>\nstartxref\n${xref}\n%%EOF`;
      return pdf;
    }
  }
  global.jspdf = global.jspdf || {};
  global.jspdf.jsPDF = jsPDF;
})(typeof window !== 'undefined' ? window : this);
